$:set -euo pipefail
test -f AGENTS.md
if test -f README.md; then cat README.md >/dev/null; fi
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
test -f .devcontainer/devcontainer.json
test ! -e config/file-metadata.json
node <<'NODE'
"use strict";
const fs=require("fs"), assert=require("assert");
const p=".devcontainer/devcontainer.json";
const source=fs.readFileSync(p,"utf8");
const beforePort='"forwardPorts":,';
const beforeAttributes='"onAutoForward": "silent",\n      "elevationRequired": false';
assert.strictEqual(source.split(beforePort).length,2,"Unexpected forwardPorts source");
assert.strictEqual(source.split(beforeAttributes).length,2,"Unexpected port attributes source");
const result=source.replace(beforePort,'"forwardPorts": [3000],').replace(beforeAttributes,'"onAutoForward": "notify"');
const doc=JSON.parse(result);
assert.deepStrictEqual(doc.forwardPorts,[3000]);
assert.deepStrictEqual(doc.portsAttributes,{"3000":{label:"MCP SSE Server",onAutoForward:"notify"}});
assert.strictEqual(doc.name,"MCP Remote Server Space");
assert.deepStrictEqual(doc.features,{"ghcr.io/devcontainers/features/node:1":{version:"lts"}});
assert.strictEqual(doc.postCreateCommand,"npm install -g @modelcontextprotocol/server-everything");
assert.strictEqual(doc.waitFor,"postCreateCommand");
fs.writeFileSync(p,result,"utf8");
assert.deepStrictEqual(JSON.parse(fs.readFileSync(p,"utf8")),doc);
console.log("JSON_VALID true");
console.log("CONFIG_CHANGE forwardPorts [3000]; onAutoForward notify; elevationRequired removed");
NODE
git add -- .devcontainer/devcontainer.json
git diff --cached --check
printf 'STAGED_DIFF\n'; git diff --cached -- .devcontainer/devcontainer.json
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
git commit -m 'Correct Codespaces MCP port forwarding configuration'
pushed=0
for i in 1 2 3 4; do
  git fetch origin main -q
  git rebase origin/main -q
  if git push origin HEAD:main; then pushed=1; break; fi
done
test "$pushed" -eq 1
printf 'PUBLISHED_COMMIT '; git rev-parse HEAD
printf 'VERIFY_REMOTE_BYTES '; cmp .devcontainer/devcontainer.json <(gh api repos/BestNameYet/Terminals/contents/.devcontainer/devcontainer.json --jq .content | base64 -d) && echo MATCH
printf 'VERIFY_REMOTE_JSON '; gh api repos/BestNameYet/Terminals/contents/.devcontainer/devcontainer.json --jq .content | base64 -d | node -e 'let s="";process.stdin.on("data",x=>s+=x);process.stdin.on("end",()=>{const c=JSON.parse(s);if(c.forwardPorts[0]!==3000||c.portsAttributes["3000"].onAutoForward!=="notify"||"elevationRequired" in c.portsAttributes["3000"])process.exit(1);console.log("VALID");})'
